import { startTransition } from "react";
import { hydrateRoot } from "react-dom/client";
import { StartClient } from "@tanstack/react-start/client";
startTransition(() => {
  hydrateRoot(document, <StartClient />);
});

import { preset } from "@tinker/core/testing";
import { database } from "./backend/database.ts";
import { mail } from "./backend/mail.ts";
import type { Database } from "./backend/database.ts";
/** Explicit local proof wiring; production factories always use Postgres and SMTP. */
export const proofDatabase = preset(database, async (_deps, ctx): Promise<Database.Handle> => {
  const [{ PGlite }, { drizzle }] = await Promise.all([
    import("@electric-sql/pglite"),
    import("drizzle-orm/pglite"),
  ]);
  const client = await PGlite.create();
  ctx.defer(() => client.close());
  return Object.assign(drizzle({ client }), {
    listen: async (wake: () => void) => client.listen("start_sync", wake),
  });
});
export const proofMail = preset(mail, async (_deps, ctx) => ({
  send: async () => {
    ctx.log("mail.recorded", { delivered: false });
  },
}));

import { createStartHandler as createStartFetch } from "@tanstack/react-start/server";
import { defaultStreamHandler as renderStartStream } from "@tanstack/react-start/server";
import type { getRouter } from "./router.tsx";
import { holdResponse } from "./scaffold/backend/body.server.ts";
import { getBackend, closeBackend } from "./scaffold/backend/entry.server.ts";
const renderRequest = createStartFetch(async (context) => {
  const router = context.router as Awaited<ReturnType<typeof getRouter>>;
  try {
    const output = await renderStartStream(context);
    if (output instanceof Response) return holdResponse(output, () => router.close());
    return { ...output, response: await holdResponse(output.response, () => router.close()) };
  } catch (error) {
    await router.close();
    throw error;
  }
});
export default {
  async fetch(request: Request) {
    const { requestContext } = await getBackend();
    return renderRequest(request, { context: requestContext });
  },
};
export const close = closeBackend;

import { createStart, createCsrfMiddleware } from "@tanstack/react-start";
import { startRequests } from "./scaffold/start.ts";
export const startInstance = createStart(() => ({
  requestMiddleware: [
    createCsrfMiddleware({ filter: (ctx) => ctx.handlerType === "serverFn" }),
    startRequests.middleware,
  ],
}));

import { fileURLToPath } from "node:url";
import { defineConfig } from "vite-plus";
import { tanstackStart } from "@tanstack/react-start/plugin/vite";
import tailwindcss from "@tailwindcss/vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  resolve: { alias: { "@": fileURLToPath(new URL("./src", import.meta.url)) } },
  plugins: [
    tanstackStart({
      importProtection: {
        behavior: "error",
        client: {
          files: [/\.server\./, /\/backend\//],
          specifiers: [
            "@tanstack/react-start/server",
            "pg",
            "nodemailer",
            "better-auth",
            "better-auth/adapters/**",
            "drizzle-orm/**",
            "@electric-sql/pglite",
          ],
        },
        server: { files: [/\.client\./] },
      },
    }),
    react(),
    tailwindcss(),
  ],
});

import { serve } from "@hono/node-server";
import { readFile } from "node:fs/promises";
import { resolve, extname } from "node:path";
import app, { close } from "../dist/server/server.js";

const publicRoot = resolve("dist/client");
const types = {
  ".js": "text/javascript",
  ".css": "text/css",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".json": "application/json",
};

async function fetchRequest(request) {
  const path = new URL(request.url).pathname;
  const folder = path.split("/").at(1);
  if (folder === "assets" || folder === "r") {
    const file = resolve(publicRoot, `.${decodeURIComponent(path)}`);
    if (!file.startsWith(`${publicRoot}/${folder}/`)) return new Response(null, { status: 404 });
    try {
      return new Response(await readFile(file), {
        headers: {
          "content-type": types[extname(file)] ?? "application/octet-stream",
          "cache-control": folder === "assets" ? "public,max-age=31536000,immutable" : "no-cache",
        },
      });
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      return new Response(null, { status: 404 });
    }
  }
  return app.fetch(request);
}

async function main() {
  const server = serve({
    hostname: process.env.HOST ?? "127.0.0.1",
    port: Number(process.env.PORT ?? 4318),
    fetch: fetchRequest,
  });
  const stopped = Promise.withResolvers();
  const stop = () => stopped.resolve();
  process.once("SIGINT", stop);
  process.once("SIGTERM", stop);
  await stopped.promise;
  const httpClosed = new Promise((done, reject) => {
    server.close((error) => (error ? reject(error) : done()));
  });
  await Promise.all([close(), httpClosed]);
  process.removeListener("SIGINT", stop);
  process.removeListener("SIGTERM", stop);
}

if (import.meta.main) await main();

import { createFileRoute } from "@tanstack/react-router";
import { isError } from "@tinker/core";
import { openSync } from "../scaffold/backend/stream.ts";
import { startRequests } from "../scaffold/start.ts";
import { isError as isAppError } from "../errors.ts";
import { readResult } from "../scaffold/backend/result.server.ts";
export const Route = createFileRoute("/api/sync")({
  server: {
    middleware: [startRequests.middleware],
    handlers: {
      GET: async ({ request, context }) => {
        /** requestStop already binds cancellation; a call signal would close a shorter child session. */
        const result = await context.session.settle(openSync, {
          rawInput: {
            search: new URL(request.url).search,
            lastEventId: request.headers.get("Last-Event-ID"),
          },
        });
        if (result.status === "failed") {
          if (isAppError(result.error, "StreamDenied")) return new Response(null, { status: 403 });
          if (isError(result.error, "DataValidationFailed"))
            return new Response(null, { status: 400 });
        }
        return readResult(result);
      },
    },
  },
});

import { createFileRoute } from "@tanstack/react-router";
import { startRequests } from "../scaffold/start.ts";
import { receiveTelemetry } from "../scaffold/telemetry/ingest.server.ts";
import { readResult } from "../scaffold/backend/result.server.ts";
export const Route = createFileRoute("/api/telemetry")({
  server: {
    middleware: [startRequests.middleware],
    handlers: {
      POST: async ({ request, context }) =>
        readResult(
          await context.session.settle(receiveTelemetry, {
            input: request,
            signal: context.signal,
          }),
        ),
    },
  },
});
